def _run(args, timeout=20):
    r = subprocess.run(args, capture_output=True, text=True, timeout=timeout)
    if r.returncode:
        raise RuntimeError(f"{args!r}: {r.returncode}: {r.stderr}")
    return r.stdout


def _sha(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def _physical(path):
    if not path.is_absolute() or path.resolve(strict=False) != path or not path.is_relative_to(B):
        raise RuntimeError(f"path escaped physical B: {path}")
    return path


def _write(path, value):
    raw = (json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n").encode()
    with path.open("xb") as f:
        f.write(raw)
        f.flush()
        os.fsync(f.fileno())


def _unit(unit, fields):
    args = ["systemctl", "--user", "show", "--all", unit]
    args.extend(part for field in fields for part in ("-p", field))
    return dict(line.split("=", 1) for line in _run(args).splitlines())


def _data_identity():
    _physical(REGISTRY)
    if REGISTRY.is_symlink() or _sha(REGISTRY) != P["registry_sha256"]:
        raise RuntimeError("portable data registry changed")
    sources = json.loads(REGISTRY.read_bytes()).get("sources", {})
    expected = P["data_resolution_map"]
    if set(sources) != set(expected) or len(expected) != 6:
        raise RuntimeError("registered F0 source membership changed")
    root, data = B.resolve(strict=True), DATA.resolve(strict=True)
    if not data.is_relative_to(root):
        raise RuntimeError("data root escaped B")
    out = {}
    for rel, bound in expected.items():
        path = DATA / rel
        entry = sources[rel]
        resolved = path.resolve(strict=True)
        st = resolved.stat()
        obs = {
            "path": str(path),
            "resolved": str(resolved),
            "islink": path.is_symlink(),
            "device": st.st_dev,
            "bytes": st.st_size,
            "inode": st.st_ino,
            "mtime_ns": st.st_mtime_ns,
            "registered_sha256": entry.get("sha256"),
        }
        keys = (
            "path",
            "resolved",
            "islink",
            "device",
            "bytes",
            "inode",
            "mtime_ns",
            "registered_sha256",
        )
        if (
            not stat.S_ISREG(st.st_mode)
            or obs != {k: bound[k] for k in keys}
            or st.st_dev != root.stat().st_dev
            or st.st_size != entry.get("original_identity", {}).get("bytes")
        ):
            raise RuntimeError(f"registered dataset alias/stat changed: {rel}")
        out[rel] = obs
    return out


def _parent():
    keys = [
        "ControlGroup",
        "MemoryCurrent",
        "MemoryHigh",
        "MemoryMax",
        "MemorySwapMax",
        "CPUQuotaPerSecUSec",
    ]
    p = _unit("wnn-campaign.slice", keys)
    if (
        not p.get("ControlGroup")
        or p["ControlGroup"] == "/"
        or (p["CPUQuotaPerSecUSec"], p["MemoryHigh"], p["MemoryMax"], p["MemorySwapMax"])
        != ("2s", "18000000000", "20000000000", "0")
        or int(p["MemoryCurrent"]) + FIT_MEMORY >= 17_000_000_000
    ):
        raise RuntimeError(f"campaign parent limits/headroom failed: {p}")
    group = Path("/sys/fs/cgroup") / p["ControlGroup"].lstrip("/")
    files = [group / "cgroup.procs", *group.rglob("cgroup.procs")]
    if len(files) > 128:
        raise RuntimeError("campaign cgroup scan exceeded bound")
    populated = {str(x): v for x in files if (v := x.read_text().strip())}
    if populated:
        raise RuntimeError(f"campaign cgroup is populated: {populated}")
    return p, populated, group


def _gpu():
    prefix = ["nvidia-smi", "-i", GPU]
    status = _run(
        prefix + ["--query-gpu=uuid,name,memory.free,memory.total", "--format=csv,noheader"]
    )
    cols = [x.strip() for x in status.strip().split(",")]
    if len(cols) != 4 or cols[0] != GPU or int(cols[2].split()[0]) * 1024 * 1024 < MIN_GPU_FREE:
        raise RuntimeError("selected GPU identity/free reserve failed")
    out = _run(prefix + ["--query-compute-apps=pid,gpu_uuid,used_memory", "--format=csv,noheader"])
    kept = []
    for row in out.splitlines():
        c = [x.strip() for x in row.split(",")]
        if row.strip().startswith("No running processes found"):
            continue
        if len(c) != 3 or c[1] != GPU:
            raise RuntimeError("unexpected selected-GPU process row")
        proc = Path("/proc") / c[0]
        try:
            owner = (proc / "cgroup").read_text().strip()
            uid = proc.stat().st_uid
            cmd = (proc / "cmdline").read_bytes().decode(errors="replace")
        except FileNotFoundError:
            kept.append({"pid": c[0], "exited_during_observation": True})
            continue
        if "wnn-campaign.slice" in owner or (uid == os.getuid() and str(B) in cmd):
            raise RuntimeError(f"selected GPU owned by another campaign process: {c[0]}")
        kept.append(
            {"pid": c[0], "uid": uid, "cgroup": owner, "used_memory": c[2], "preserved": True}
        )
    return status.strip(), kept


def _source_identity():
    raw = base64.b64decode(P["source_manifest_b64"], validate=True)
    if hashlib.sha256(raw).hexdigest() != P["source_manifest_sha256"]:
        raise RuntimeError("embedded source manifest changed")
    manifest = json.loads(raw)
    if (
        manifest.get("source_commit") != P["source_commit"]
        or manifest.get("source_root") != str(SOURCE)
        or len(manifest.get("files", [])) != 167
        or P["source_commit"] != "68ff682977b822f38351aac0f621146f5f13b440"
    ):
        raise RuntimeError("source manifest identity differs")
    expected = {item["path"] for item in manifest["files"]}
    actual = set()
    for item in manifest["files"]:
        path = SOURCE / item["path"]
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_size != item["bytes"]
            or _sha(path) != item["sha256"]
        ):
            raise RuntimeError(f"source differs from manifest: {item['path']}")
        actual.add(item["path"])
    existing = {
        x.relative_to(SOURCE).as_posix() for x in SOURCE.rglob("*") if x.is_file() or x.is_symlink()
    }
    if actual != expected or existing != expected or SOURCE.is_symlink() or not SOURCE.is_dir():
        raise RuntimeError("staged source inventory is incomplete, extra, or unsafe")
    return len(actual)


def _metadata_identity():
    _physical(CONTRACT)
    if CONTRACT.is_symlink() or _sha(CONTRACT) != P["contract_sha256"]:
        raise RuntimeError("cache execution contract changed")
    doc = json.loads(CONTRACT.read_bytes())
    if doc.get("split_sha256") != P["split_sha256"] or doc.get("teacher_order") != [3, 4, 5]:
        raise RuntimeError("cache contract split/order differs")
    pins = {"preparation/TEACHER_CACHE_EXECUTION_CONTRACT_R1.json": P["contract_sha256"]}
    for item in P["teacher_metadata"]:
        path = _physical(TEACHER_ROOT / item["path"])
        if path.is_symlink() or _sha(path) != item["sha256"]:
            raise RuntimeError(f"accepted teacher metadata changed: {item['run']}")
        pins[item["path"]] = item["sha256"]
    return pins


def _group_list(value: object, label: str) -> list[int]:
    if not isinstance(value, list) or any(type(group) is not int for group in value):
        raise RuntimeError(f"cache group membership is not an integer list: {label}")
    if len(value) != len(set(value)):
        raise RuntimeError(f"cache group membership has duplicates: {label}")
    return value


def _validate_cache_membership(
    metadata: dict[str, object], canonical_split: dict[str, object]
) -> None:
    fit = metadata.get("fit_groups")
    expected_fit = canonical_split.get("fit")
    evaluation = canonical_split.get("evaluation")
    if (
        not isinstance(fit, dict)
        or not isinstance(expected_fit, dict)
        or not isinstance(evaluation, dict)
    ):
        raise RuntimeError("canonical split membership is missing")
    train = _group_list(fit.get("train"), "fit train")
    valid = _group_list(fit.get("valid"), "fit valid")
    expected_train = _group_list(expected_fit.get("train"), "canonical fit train")
    expected_valid = _group_list(expected_fit.get("valid"), "canonical fit valid")
    outer = _group_list(metadata.get("evaluation_valid_groups"), "metadata outer valid")
    expected_outer = _group_list(evaluation.get("valid"), "canonical outer valid")
    counts = (len(train), len(valid), len(outer))
    if (
        train != expected_train
        or valid != expected_valid
        or outer != expected_outer
        or counts != (10535, 1405, 468)
    ):
        raise RuntimeError("cache fit memberships differ from canonical split by namespace")
    if set(valid) & set(outer):
        raise RuntimeError("cache fit-valid membership overlaps outer-valid membership")
    files = metadata.get("files")
    if not isinstance(files, dict):
        raise RuntimeError("cache file membership manifest is missing")
    for split, groups in (("train", train), ("valid", valid)):
        entry = files.get(f"main_homogeneous_{split}")
        if not isinstance(entry, dict):
            raise RuntimeError(f"cache file membership is missing: {split}")
        rows = _group_list(entry.get("row_groups"), f"output {split}")
        if len(rows) != len(groups) or set(rows) != set(groups):
            raise RuntimeError(f"cache output membership differs: {split}")
    # Canonical trainer validation compares row order to the target-index order in-unit.


def _cache_identity():
    p = P["cache_binding"]
    fields = (
        "acceptance_path",
        "acceptance_sha256",
        "exact_stop_path",
        "exact_stop_sha256",
        "unit",
        "invocation_id",
        "metadata_sha256",
    )
    if any(not p.get(k) for k in fields) or any(
        v is None for s in ("train", "valid") for v in p["arrays"][s].values()
    ):
        raise RuntimeError("cache root acceptance/stop/metadata/output-stat binding is pending")
    for k, sha in (
        ("acceptance_path", "acceptance_sha256"),
        ("exact_stop_path", "exact_stop_sha256"),
    ):
        path = Path(p[k])
        _physical(path)
        if path.is_symlink() or _sha(path) != p[sha]:
            raise RuntimeError(f"cache receipt pin changed/escaped B: {k}")
    accept = json.loads(Path(p["acceptance_path"]).read_bytes())
    if accept.get("status") != "ACCEPTED":
        raise RuntimeError("cache root receipt is not accepted")
    stop = json.loads(Path(p["exact_stop_path"]).read_bytes())
    before = stop.get("before", {}).get(p["unit"], {})
    after = stop.get("after", {}).get(p["unit"], {})
    done = stop.get("stop", {}).get(p["unit"], {})
    if (
        before.get("InvocationID") != p["invocation_id"]
        or before.get("ExecMainStatus") != "0"
        or done.get("returncode") != 0
        or after.get("LoadState") != "not-found"
        or after.get("ActiveState") != "inactive"
        or after.get("SubState") != "dead"
        or after.get("InvocationID") != ""
        or stop.get("populated") != {}
    ):
        raise RuntimeError("cache exact-stop does not bind the accepted completed unit")
    _physical(CACHE)
    mp = CACHE / "metadata.json"
    if mp.is_symlink() or mp.stat().st_size > 512_000 or _sha(mp) != p["metadata_sha256"]:
        raise RuntimeError("accepted cache metadata changed")
    m = json.loads(mp.read_bytes())
    target = m.get("target_contract", {})
    if (
        m.get("cache_profile") != "cleanfold_homogeneous_strong_t3_v1"
        or m.get("split_manifest_sha256") != P["split_sha256"]
        or m.get("homogeneous_scale") != 0.8125
        or m.get("stored_targets") != ["main_homogeneous"]
        or m.get("root_execution_contract", {}).get("sha256") != P["contract_sha256"]
    ):
        raise RuntimeError("cache source/target metadata differs")
    if target != {
        "formula": "float32(0.8125 * float32_mean(three_epoch2_predictions))",
        "teacher_epoch": 2,
        "teacher_mean": "unweighted arithmetic mean in float32",
        "clipping": "none during cache construction",
        "coefficient_multiplier": 0.8125,
    }:
        raise RuntimeError("cache arithmetic contract differs")
    _physical(SPLIT)
    if SPLIT.is_symlink():
        raise RuntimeError("canonical split path became a symlink")
    split_raw = SPLIT.read_bytes()
    if len(split_raw) > 4 * (1 << 20) or hashlib.sha256(split_raw).hexdigest() != P["split_sha256"]:
        raise RuntimeError("canonical split bytes changed or exceeded bound")
    _validate_cache_membership(m, json.loads(split_raw))
    coeff = m.get("source_coefficients", [])
    expected = [
        ("fg19_t3_h384x2_e3_s3_v1", 3),
        ("fg19_t3_h384x2_e3_s4_v1", 4),
        ("fg19_t3_h384x2_e3_s5_v1", 5),
    ]
    if [
        (x.get("run"), x.get("epoch"), x.get("family"), float(x.get("coefficient", 0)))
        for x in coeff
    ] != [(r, 2, "strong", 0.1) for r, _ in expected]:
        raise RuntimeError("cache teacher order/coefficients differ")
    stats = {}
    for split, rows in (("train", 10535), ("valid", 1405)):
        name = f"main_homogeneous_{split}.npy"
        path = _physical(CACHE / name)
        pin = p["arrays"][split]
        st = os.stat(path, follow_symlinks=False)
        observed = {
            "bytes": st.st_size,
            "device": st.st_dev,
            "inode": st.st_ino,
            "mtime_ns": st.st_mtime_ns,
        }
        entry = m.get("files", {}).get(f"main_homogeneous_{split}", {})
        if (
            path.is_symlink()
            or not stat.S_ISREG(st.st_mode)
            or observed != pin
            or entry.get("path") != name
            or entry.get("bytes") != st.st_size
            or entry.get("shape") != [rows, 20000, 2]
            or entry.get("dtype") != "float32"
        ):
            raise RuntimeError(f"cache output identity/stat/membership differs: {name}")
        stats[split] = observed
    return {
        "acceptance_sha256": p["acceptance_sha256"],
        "exact_stop_sha256": p["exact_stop_sha256"],
        "unit": p["unit"],
        "invocation_id": p["invocation_id"],
        "metadata_sha256": p["metadata_sha256"],
        "array_stats_only": stats,
    }


