def _decode_payloads():
    """Validate embedded, source-qualified bytes before any remote filesystem write."""
    payload = json.loads(base64.b64decode(STAGED_PAYLOADS_B64, validate=True))
    files = payload.get("files")
    expected = {
        "PARENT_TERMINAL_ACCEPTANCE.json": PARENT_ACCEPTANCE_SHA256,
        "PARENT_EXACT_STOP.json": PARENT_EXACT_STOP_SHA256,
        "DICTIONARY_ACCEPTANCE.json": DICTIONARY_ACCEPTANCE_SHA256,
        PROFILE_PROBE: None,
        PROFILE_CONTRACT: None,
        PROFILE_HELPER: PROFILE_HELPER_SHA256,
    }
    if not isinstance(files, dict) or set(files) != set(expected):
        raise RuntimeError("private profile staging payload membership changed")
    raw_files = {}
    pins = {}
    for name, item in files.items():
        if not isinstance(item, dict) or item.get("source_path") is None:
            raise RuntimeError(f"staged file source is missing: {name}")
        raw = base64.b64decode(item.get("raw_b64", ""), validate=True)
        digest = hashlib.sha256(raw).hexdigest()
        if digest != item.get("sha256") or (
            expected[name] is not None and digest != expected[name]
        ):
            raise RuntimeError(f"staged input bytes differ from their bound SHA: {name}")
        if (
            name == PROFILE_PROBE
            and digest != "446e679ddae0f05225209950d928790264c8cd57fb8836b79f671d06d03be9e4"
        ):
            raise RuntimeError("profile probe source hash changed")
        if (
            name == PROFILE_CONTRACT
            and digest != "ab68d868261106a7548b649243f4a645ece926b6138d683c731841cfb9f0b7c5"
        ):
            raise RuntimeError("profile contract source hash changed")
        if name == PROFILE_HELPER and digest != PROFILE_HELPER_SHA256:
            raise RuntimeError("profile loader helper source hash changed")
        raw_files[name] = raw
        pins[name] = digest
    acceptance = json.loads(raw_files["PARENT_TERMINAL_ACCEPTANCE.json"])
    native = acceptance.get("native_unit", {})
    checkpoint = acceptance.get("files", {}).get("model_ep3.pt", {})
    if (
        acceptance.get("status") != "ACCEPTED"
        or acceptance.get("unit") != PARENT_UNIT
        or acceptance.get("invocation_id") != PARENT_INVOCATION
        or acceptance.get("selected_epoch") != 3
        or acceptance.get("successful_updates") != 29840
        or acceptance.get("nonfinite_updates") != 0
        or checkpoint.get("sha256") != PARENT_EP3_SHA256
        or checkpoint.get("bytes") != PARENT_EP3_BYTES
        or native.get("InvocationID") != PARENT_INVOCATION
        or native.get("MainPID") != "0"
        or native.get("ExecMainCode") != "1"
        or native.get("ExecMainStatus") != "0"
    ):
        raise RuntimeError("embedded parent acceptance is not the bound successful epoch-3 fit")
    stop = json.loads(raw_files["PARENT_EXACT_STOP.json"])
    before, after, stopped = stop.get("before", {}), stop.get("after", {}), stop.get("stop", {})
    if (
        stop.get("unit") != PARENT_UNIT
        or stop.get("invocation_id") != PARENT_INVOCATION
        or before.get("InvocationID") != PARENT_INVOCATION
        or before.get("ActiveState") != "active"
        or before.get("SubState") != "exited"
        or before.get("MainPID") != "0"
        or stopped.get("returncode") != 0
        or after.get("LoadState") != "not-found"
        or after.get("ActiveState") != "inactive"
        or after.get("SubState") != "dead"
        or after.get("MainPID") != "0"
        or after.get("InvocationID") != ""
        or stop.get("populated_after") != {}
    ):
        raise RuntimeError("embedded parent exact-stop receipt does not bind the accepted fit")
    dictionary = json.loads(raw_files["DICTIONARY_ACCEPTANCE.json"])
    cache = dictionary.get("cache", {})
    if (
        dictionary.get("status") != "ARTIFACT_AND_PROVENANCE_ACCEPTED"
        or cache.get("sha256") != DICTIONARY_SHA256
        or cache.get("bytes") != DICTIONARY_BYTES
        or Path(cache.get("path", "")).resolve(strict=False)
        != DICTIONARY_CACHE.resolve(strict=False)
    ):
        raise RuntimeError("embedded dictionary acceptance differs from the shared fold-0 cache")
    return raw_files, pins


def _dictionary_identity() -> dict[str, object]:
    """Verify only the small accepted dictionary artifact, without deserializing it."""
    path = DICTIONARY_CACHE.resolve(strict=True)
    _physical(path)
    st = os.stat(path, follow_symlinks=False)
    if (
        not stat.S_ISREG(st.st_mode)
        or st.st_size != DICTIONARY_BYTES
        or _sha(path) != DICTIONARY_SHA256
    ):
        raise RuntimeError("shared dictionary cache bytes/stat differ from the accepted artifact")
    return {
        "path": str(path),
        "bytes": st.st_size,
        "device": st.st_dev,
        "inode": st.st_ino,
        "sha256": DICTIONARY_SHA256,
    }


def _parent_checkpoint_identity() -> dict[str, object]:
    """Recheck the accepted initialization checkpoint before creating profile inputs."""
    path = _physical(PARENT_CHECKPOINT)
    st = os.stat(path, follow_symlinks=False)
    if (
        path.is_symlink()
        or not stat.S_ISREG(st.st_mode)
        or st.st_size != PARENT_EP3_BYTES
        or _sha(path) != PARENT_EP3_SHA256
    ):
        raise RuntimeError("accepted parent epoch-3 checkpoint bytes/stat changed")
    return {
        "path": str(path),
        "bytes": st.st_size,
        "sha256": PARENT_EP3_SHA256,
        "device": st.st_dev,
        "inode": st.st_ino,
        "mtime_ns": st.st_mtime_ns,
    }


def _write_payload(path, raw):
    with path.open("xb") as stream:
        os.fchmod(stream.fileno(), 0o600)
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())


def _sync_directory(path):
    descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


